<!doctype html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="Aman Private School — Learn, grow and succeed.">
    <title>{{ $title ?? 'Aman Private School' }}</title>
    <style>
        :root{--navy:#082d4d;--blue:#12547d;--green:#099b75;--mint:#e9f8f3;--gold:#f3b23d;--ink:#17304b;--muted:#64778a;--line:#dce7ed;--paper:#f6fafb}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);font:16px/1.65 Arial,sans-serif;background:#fff}a{color:inherit;text-decoration:none}.wrap{width:min(1160px,calc(100% - 36px));margin:auto}.top{background:var(--navy);color:#d7e6ef;font-size:13px}.top .wrap{min-height:38px;display:flex;justify-content:space-between;align-items:center}.top-contact{display:flex;gap:20px}.header{position:sticky;top:0;z-index:30;background:#fff;box-shadow:0 2px 14px #082d4d12}.nav{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:25px}.brand{display:flex;align-items:center;gap:11px;color:var(--navy);font-size:19px;font-weight:850;white-space:nowrap}.brand img{width:51px;height:51px;display:block}.brand small{display:block;color:var(--green);font-size:11px;font-weight:700}.links{display:flex;align-items:center;gap:22px;color:#365169;font-size:14px;font-weight:750}.links a:hover,.links a.active{color:var(--green)}.button{display:inline-flex;align-items:center;justify-content:center;min-height:45px;padding:0 20px;border:1px solid var(--green);border-radius:7px;background:var(--green);color:#fff;font-weight:800;transition:.2s}.button:hover{background:#057556;transform:translateY(-2px)}.button.light{background:#fff;border-color:#b7cad6;color:var(--navy)}.menu{display:none;border:0;background:transparent;color:var(--navy);font-size:27px;cursor:pointer}.page-hero{padding:87px 0 76px;color:#fff;background:radial-gradient(circle at 79% 14%,#20b99650 0 13%,transparent 14%),radial-gradient(circle at 82% 74%,#f3b23d3b 0 12%,transparent 13%),linear-gradient(120deg,var(--navy),var(--blue))}.page-hero .eyebrow{color:#8de9ce}.page-hero h1{max-width:700px;margin:0;font-size:clamp(38px,5vw,60px);line-height:1.12}.page-hero p:last-child{max-width:620px;margin:17px 0 0;color:#e0ebf2;font-size:18px}section{padding:80px 0}.eyebrow{margin:0 0 8px;color:var(--green);font-size:13px;font-weight:900;letter-spacing:.8px;text-transform:uppercase}h2{margin:0;color:var(--navy);font-size:clamp(28px,4vw,42px);line-height:1.28}.lead,.muted{color:var(--muted)}.section-head{max-width:700px;margin:0 auto 39px;text-align:center}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:27px;border:1px solid var(--line);border-radius:11px;background:#fff;box-shadow:0 8px 22px #082d4d08}.card:hover{transform:translateY(-4px);box-shadow:0 18px 34px #082d4d12}.icon{display:grid;place-items:center;width:52px;height:52px;margin-bottom:17px;border-radius:10px;background:var(--mint);color:var(--green);font-size:25px}.card h3{margin:0 0 8px;color:var(--navy);font-size:20px}.card p{margin:0;color:var(--muted);font-size:14px}.split{display:grid;grid-template-columns:1fr 1fr;gap:52px;align-items:center}.visual{min-height:360px;position:relative;overflow:hidden;border-radius:14px;background:linear-gradient(145deg,#0d4f78,#0a9377)}.visual:before{content:'';position:absolute;inset:30px;border:1px solid #ffffff54;border-radius:11px}.visual:after{content:'A';position:absolute;left:42px;bottom:-54px;color:#ffffff20;font-size:300px;font-weight:900;line-height:1}.checks{display:grid;grid-template-columns:1fr 1fr;gap:11px;padding:0;list-style:none;color:#3b576e;font-weight:700}.checks li:before{content:'✓';display:inline-grid;place-items:center;width:20px;height:20px;margin-right:8px;border-radius:50%;background:var(--green);color:#fff;font-size:11px}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.stat{padding:16px 10px;border:1px solid var(--line);border-radius:8px;text-align:center}.stat b{display:block;color:var(--green);font-size:28px}.stat span{color:var(--muted);font-size:12px;font-weight:700}.tint{background:var(--paper)}.steps{display:grid;gap:14px}.step{display:flex;align-items:center;gap:14px;padding:17px;border:1px solid var(--line);border-radius:9px;background:#fff}.step b{display:grid;place-items:center;flex:0 0 33px;width:33px;height:33px;border-radius:50%;background:var(--green);color:#fff}.news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.news-card{border:1px solid var(--line);border-radius:11px;overflow:hidden;background:#fff}.news-image{height:155px;background:linear-gradient(135deg,#0b3a61,#0c9a73)}.news-card:nth-child(2) .news-image{background:linear-gradient(135deg,#14638b,#f3b23d)}.news-card:nth-child(3) .news-image{background:linear-gradient(135deg,#0b9b75,#073356)}.news-body{padding:20px}.news-body time{color:var(--green);font-size:12px;font-weight:850}.news-body h3{margin:7px 0;color:var(--navy);font-size:19px}.news-body p{margin:0;color:var(--muted);font-size:14px}.contact-grid{display:grid;grid-template-columns:1fr .85fr;gap:44px}.contact-list{display:grid;gap:12px;margin-top:23px}.contact-item{padding:16px;border:1px solid var(--line);border-radius:9px;background:#fff}.contact-item b,.contact-item span{display:block}.contact-item span{color:var(--muted);font-size:14px}.portal{padding:31px;border-radius:12px;background:var(--green);color:#fff}.portal h3{margin-top:0;font-size:25px}.portal p{color:#ddfff5}.portal a{display:flex;justify-content:space-between;margin-top:10px;padding:12px 14px;border-radius:7px;background:#ffffff18;font-weight:750}.footer{padding:30px 0;background:#062741;color:#c3d4df;font-size:13px}.footer .wrap{display:flex;justify-content:space-between;gap:18px}.footer b{color:#fff;font-size:16px}@media(max-width:850px){.menu{display:block}.links{position:absolute;top:78px;right:0;left:0;display:none;flex-direction:column;align-items:stretch;gap:0;padding:12px 20px 20px;background:#fff;border-top:1px solid var(--line)}.links.open{display:flex}.links a{padding:9px 0}.links .button{margin-top:8px}.cards,.news-grid{grid-template-columns:repeat(2,1fr)}.split,.contact-grid{grid-template-columns:1fr}.visual{min-height:280px}.news-grid article:first-child{grid-column:span 2}}@media(max-width:520px){.top{display:none}.wrap{width:min(100% - 28px,1160px)}.nav{min-height:70px}.brand{font-size:16px}.brand img{width:43px;height:43px}.links{top:70px}.page-hero{padding:65px 0}.cards,.news-grid,.stat-grid,.checks{grid-template-columns:1fr}section{padding:60px 0}.news-grid article:first-child{grid-column:auto}.footer .wrap{display:block}.footer span{display:block;margin-top:7px}}
    </style>
</head>
