<header class="header"><nav class="wrap nav"><a class="brand" href="{{ route('home') }}"><img src="{{ asset('aman-logo.svg') }}" alt="Aman Private School logo"><span>Aman Private School<small>Learn. Grow. Succeed.</small></span></a><button class="menu" type="button" aria-label="Open menu">☰</button><div class="links"><a class="{{ request()->routeIs('home') ? 'active' : '' }}" href="{{ route('home') }}">Home</a><a class="{{ request()->routeIs('about') ? 'active' : '' }}" href="{{ route('about') }}">About</a><a class="{{ request()->routeIs('services') ? 'active' : '' }}" href="{{ route('services') }}">Services</a><a class="{{ request()->routeIs('admissions') ? 'active' : '' }}" href="{{ route('admissions') }}">Admissions</a><a class="{{ request()->routeIs('news') ? 'active' : '' }}" href="{{ route('news') }}">News</a><a class="{{ request()->routeIs('contact') ? 'active' : '' }}" href="{{ route('contact') }}">Contact</a><a class="button" href="{{ route('login.portal') }}">Login Portal</a></div></nav></header>
